            const l = { id: 'l' + Date.now().toString(36), name: String(name).trim().slice(0, 40), color: TOK_LIST_COLORS.find(c => !used.has(c)) || TOK_LIST_COLORS[d.lists.length % TOK_LIST_COLORS.length] };
            d.lists.push(l);
